#!/usr/bin/env perl
# -*- coding: utf-8 -*-
use strict;
use warnings;
use Getopt::Long qw(GetOptions);
use File::Basename qw(dirname);
use File::Path qw(make_path);
use Cwd qw(abs_path);
use IO::Handle;

STDOUT->autoflush(1);
STDERR->autoflush(1);

# ============================================================
# Script:
#   extract_sa_split_reads.pl
#
# Purpose:
#   Extract deletion-like SA split-read events from SAMPLE.target.bam.
#
# Pipeline logic:
#   1. Input BAM is already SAMPLE.target.bam generated by
#      extract_target_bam.pl.
#   2. The target BAM already contains HCM core genes plus flank.
#   3. This script scans the whole target BAM directly.
#   4. Only same-chromosome SA events with a deletion-like gap are
#      written to the output file.
#
# Required command-line arguments:
#   --conf / --config
#   --bam
#   --sample
#   --out
#
# Required config parameters:
#   SAMTOOLS
#   MIN_MAPQ
#   EXCLUDE_DUPLICATES
#   SPLIT_READ_THREADS
#
# Output:
#   One row represents one deletion-like SA split-read event.
#
# Output columns:
#   Sample
#   Read_Name
#   Flag
#   Primary_Chrom
#   Primary_Start
#   Primary_End
#   Primary_CIGAR
#   Primary_MAPQ
#   Primary_Strand
#   SA_Chrom
#   SA_Start
#   SA_End
#   SA_CIGAR
#   SA_MAPQ
#   SA_Strand
#   SA_NM
#   Left_Breakpoint
#   Right_Breakpoint
#   SV_Chrom
#   SV_Start
#   SV_End
#   SV_Length
#   Junction_Type
#   SA_Tag
# ============================================================

my $conf   = "";
my $bam    = "";
my $sample = "";
my $out    = "";
my $help   = 0;

GetOptions(
    "conf=s"   => \$conf,
    "config=s" => \$conf,
    "bam=s"    => \$bam,
    "sample=s" => \$sample,
    "out=s"    => \$out,
    "help"     => \$help,
) or die usage();

if ($help) {
    print usage();
    exit 0;
}

die usage()
    unless defined $conf   && $conf   ne ""
        && defined $bam    && $bam    ne ""
        && defined $sample && $sample ne ""
        && defined $out    && $out    ne "";

# ------------------------------------------------------------
# Validate runtime I/O
# ------------------------------------------------------------
$conf = abs_path($conf) if -e $conf;
die "[ERROR] Config file not found: $conf\n"
    unless defined $conf && -s $conf;
die "[ERROR] Config path must be absolute after resolution: $conf\n"
    unless $conf =~ m{^/};

$bam = abs_path($bam) if -e $bam;
die "[ERROR] BAM file not found: $bam\n"
    unless defined $bam && -s $bam;
die "[ERROR] BAM path must be absolute after resolution: $bam\n"
    unless $bam =~ m{^/};
die "[ERROR] BAM file must end with .bam: $bam\n"
    unless $bam =~ /\.bam$/i;

check_bam_index($bam);

die "[ERROR] Invalid sample name: $sample\n"
  . "        Sample name can only contain letters, numbers, dot, underscore and hyphen.\n"
    unless $sample =~ /^[A-Za-z0-9_.-]+$/;

die "[ERROR] Output path must be absolute: $out\n"
    unless defined $out && $out =~ m{^/};

my $outdir = dirname($out);
make_path($outdir) unless -d $outdir;
die "[ERROR] Cannot create output directory: $outdir\n"
    unless -d $outdir;

# ------------------------------------------------------------
# Read config
# ------------------------------------------------------------
my %CFG = read_conf($conf);

if (exists $CFG{ANALYZE_CORE_GENES_ONLY}) {
    die "[ERROR] ANALYZE_CORE_GENES_ONLY has been removed.\n"
      . "        HCMExonDel now always uses target BAM generated from HCM core genes.\n"
      . "        Please delete ANALYZE_CORE_GENES_ONLY from the config file.\n";
}

my $samtools = get_conf_required(\%CFG, "SAMTOOLS");
check_executable($samtools, "SAMTOOLS");

my $min_mapq = get_conf_required(\%CFG, "MIN_MAPQ");
validate_nonnegative_integer("MIN_MAPQ", $min_mapq);

my $exclude_duplicates = get_conf_required(\%CFG, "EXCLUDE_DUPLICATES");
validate_bool_01("EXCLUDE_DUPLICATES", $exclude_duplicates);

my $threads = get_conf_required(\%CFG, "SPLIT_READ_THREADS");
validate_positive_integer("SPLIT_READ_THREADS", $threads);

# ------------------------------------------------------------
# SAM flag filtering
# ------------------------------------------------------------

# Require:
#   0x1 = paired-end read
#
# Do not require 0x2 properly paired, because split-read evidence may
# come from reads whose pair is not marked as proper.
my $REQUIRE_FLAG = 1;

# Exclude:
#   0x4   read unmapped
#   0x100 secondary alignment
#   0x200 QC fail
#   0x800 supplementary alignment
#
# Duplicate reads are excluded only when EXCLUDE_DUPLICATES=1.
my $EXCLUDE_FLAG = 4 + 256 + 512 + 2048;

if ($exclude_duplicates == 1) {
    $EXCLUDE_FLAG += 1024;
}

# ------------------------------------------------------------
# Output
# ------------------------------------------------------------
open my $OUT, ">", $out
    or die "[ERROR] Cannot write output file: $out\n";

my @HEADER = qw(
    Sample
    Read_Name
    Flag
    Primary_Chrom
    Primary_Start
    Primary_End
    Primary_CIGAR
    Primary_MAPQ
    Primary_Strand
    SA_Chrom
    SA_Start
    SA_End
    SA_CIGAR
    SA_MAPQ
    SA_Strand
    SA_NM
    Left_Breakpoint
    Right_Breakpoint
    SV_Chrom
    SV_Start
    SV_End
    SV_Length
    Junction_Type
    SA_Tag
);

print $OUT join("\t", @HEADER), "\n";

# ------------------------------------------------------------
# Run samtools view on the whole target BAM
# ------------------------------------------------------------
my @cmd = (
    $samtools, "view",
    "-@", $threads,
    "-f",  $REQUIRE_FLAG,
    "-F",  $EXCLUDE_FLAG,
    "-q",  $min_mapq,
    $bam,
);

print STDERR "[INFO] SA split-read extraction started\n";
print STDERR "[INFO] Config: $conf\n";
print STDERR "[INFO] Sample: $sample\n";
print STDERR "[INFO] BAM: $bam\n";
print STDERR "[INFO] Output: $out\n";
print STDERR "[INFO] SAMTOOLS: $samtools\n";
print STDERR "[INFO] MIN_MAPQ: $min_mapq\n";
print STDERR "[INFO] EXCLUDE_DUPLICATES: $exclude_duplicates\n";
print STDERR "[INFO] SPLIT_READ_THREADS: $threads\n";
print STDERR "[INFO] Require FLAG: $REQUIRE_FLAG\n";
print STDERR "[INFO] Exclude FLAG: $EXCLUDE_FLAG\n";
print STDERR "[CMD] ", join(" ", map { shell_quote($_) } @cmd), "\n";

open my $SAM, "-|", @cmd
    or die "[ERROR] Failed to run samtools view on BAM: $bam\n";

# ------------------------------------------------------------
# Counters
# ------------------------------------------------------------
my $total_records              = 0;
my $records_with_sa            = 0;
my $qualified_primary_records  = 0;
my $total_sa_entries           = 0;
my $qualified_sa_entries       = 0;
my $deletion_gap_events        = 0;

my $skipped_bad_sam            = 0;
my $skipped_flag               = 0;
my $skipped_primary_mapq       = 0;
my $skipped_primary_cigar      = 0;
my $skipped_no_sa              = 0;
my $skipped_bad_sa             = 0;
my $skipped_sa_mapq            = 0;
my $skipped_non_deletion_event = 0;

while (my $line = <$SAM>) {
    chomp $line;
    next if $line =~ /^\s*$/;

    $total_records++;

    my @f = split /\t/, $line;
    unless (@f >= 11) {
        $skipped_bad_sam++;
        next;
    }

    my ($qname, $flag, $rname, $pos, $mapq, $cigar) = @f[0 .. 5];

    unless (defined $flag && $flag =~ /^\d+$/) {
        $skipped_bad_sam++;
        next;
    }

    # Redundant but explicit validation.
    unless (
        is_paired($flag)
        && !is_unmapped($flag)
        && !is_secondary($flag)
        && !is_supplementary($flag)
    ) {
        $skipped_flag++;
        next;
    }

    if ($exclude_duplicates == 1 && is_duplicate($flag)) {
        $skipped_flag++;
        next;
    }

    unless (defined $mapq && $mapq =~ /^\d+$/ && $mapq >= $min_mapq) {
        $skipped_primary_mapq++;
        next;
    }

    unless (defined $pos && $pos =~ /^\d+$/ && $pos >= 1) {
        $skipped_primary_cigar++;
        next;
    }

    unless (defined $cigar && $cigar ne "*") {
        $skipped_primary_cigar++;
        next;
    }

    my $primary_ref_len = cigar_ref_length($cigar);

    unless ($primary_ref_len > 0) {
        $skipped_primary_cigar++;
        next;
    }

    my ($has_sa, $sa_tag) = parse_sa_tag(@f);

    unless ($has_sa) {
        $skipped_no_sa++;
        next;
    }

    $records_with_sa++;

    my @sa_entries = parse_sa_entries($sa_tag);

    unless (@sa_entries) {
        $skipped_bad_sa++;
        next;
    }

    my $primary_start  = $pos;
    my $primary_end    = $pos + $primary_ref_len - 1;
    my $primary_strand = is_reverse($flag) ? "-" : "+";

    $qualified_primary_records++;

    for my $sa (@sa_entries) {
        $total_sa_entries++;

        unless (
            defined $sa->{chr}
            && defined $sa->{pos}
            && defined $sa->{strand}
            && defined $sa->{cigar}
            && defined $sa->{mapq}
            && $sa->{chr} ne ""
            && $sa->{pos} =~ /^\d+$/
            && $sa->{pos} >= 1
            && $sa->{strand} =~ /^[+-]$/
            && $sa->{cigar} ne ""
            && $sa->{cigar} ne "*"
            && $sa->{mapq} =~ /^\d+$/
        ) {
            $skipped_bad_sa++;
            next;
        }

        if ($sa->{mapq} < $min_mapq) {
            $skipped_sa_mapq++;
            next;
        }

        my $sa_ref_len = cigar_ref_length($sa->{cigar});

        unless ($sa_ref_len > 0) {
            $skipped_bad_sa++;
            next;
        }

        my $sa_start = $sa->{pos};
        my $sa_end   = $sa->{pos} + $sa_ref_len - 1;

        $qualified_sa_entries++;

        my %sv = infer_sv_interval(
            primary_chr   => $rname,
            primary_start => $primary_start,
            primary_end   => $primary_end,
            sa_chr        => $sa->{chr},
            sa_start      => $sa_start,
            sa_end        => $sa_end,
        );

        unless ($sv{junction_type} eq "Deletion_Gap") {
            $skipped_non_deletion_event++;
            next;
        }

        my %record = (
            Sample           => $sample,
            Read_Name        => $qname,
            Flag             => $flag,
            Primary_Chrom    => $rname,
            Primary_Start    => $primary_start,
            Primary_End      => $primary_end,
            Primary_CIGAR    => $cigar,
            Primary_MAPQ     => $mapq,
            Primary_Strand   => $primary_strand,
            SA_Chrom         => $sa->{chr},
            SA_Start         => $sa_start,
            SA_End           => $sa_end,
            SA_CIGAR         => $sa->{cigar},
            SA_MAPQ          => $sa->{mapq},
            SA_Strand        => $sa->{strand},
            SA_NM            => $sa->{nm},
            Left_Breakpoint  => $sv{left_breakpoint},
            Right_Breakpoint => $sv{right_breakpoint},
            SV_Chrom         => $sv{sv_chr},
            SV_Start         => $sv{sv_start},
            SV_End           => $sv{sv_end},
            SV_Length        => $sv{sv_length},
            Junction_Type    => $sv{junction_type},
            SA_Tag           => $sa_tag,
        );

        print $OUT join("\t", map { defined $record{$_} ? $record{$_} : "NA" } @HEADER), "\n";

        $deletion_gap_events++;
    }
}

close $SAM
    or die "[ERROR] samtools view command failed for BAM: $bam\n";

close $OUT;

die "[ERROR] Output file was not generated: $out\n"
    unless -e $out;

# ------------------------------------------------------------
# Summary
# ------------------------------------------------------------
print STDERR "[INFO] SA split-read extraction finished\n";
print STDERR "[INFO] Total SAM records after samtools filtering: $total_records\n";
print STDERR "[INFO] Records with SA tag: $records_with_sa\n";
print STDERR "[INFO] Qualified primary records: $qualified_primary_records\n";
print STDERR "[INFO] Total SA entries parsed: $total_sa_entries\n";
print STDERR "[INFO] Qualified SA entries: $qualified_sa_entries\n";
print STDERR "[INFO] Deletion-gap events written: $deletion_gap_events\n";
print STDERR "[INFO] Skipped bad SAM records: $skipped_bad_sam\n";
print STDERR "[INFO] Skipped by flag: $skipped_flag\n";
print STDERR "[INFO] Skipped by primary MAPQ: $skipped_primary_mapq\n";
print STDERR "[INFO] Skipped by primary CIGAR/POS: $skipped_primary_cigar\n";
print STDERR "[INFO] Skipped without SA tag: $skipped_no_sa\n";
print STDERR "[INFO] Skipped bad SA entries: $skipped_bad_sa\n";
print STDERR "[INFO] Skipped by SA MAPQ: $skipped_sa_mapq\n";
print STDERR "[INFO] Skipped non-deletion SA events: $skipped_non_deletion_event\n";
print STDERR "[INFO] Output: $out\n";

exit 0;

# ============================================================
# Config helpers
# ============================================================

sub read_conf {
    my ($file) = @_;

    my %cfg;

    open my $FH, "<", $file
        or die "[ERROR] Cannot open config file: $file\n";

    while (my $line = <$FH>) {
        chomp $line;
        $line =~ s/\r$//;

        next if $line =~ /^\s*$/;
        next if $line =~ /^\s*#/;

        # Remove inline comments:
        # KEY=value   # comment
        $line =~ s/\s+#.*$//;

        next unless $line =~ /^\s*([^=\s]+)\s*=\s*(.*?)\s*$/;

        my ($key, $val) = ($1, $2);

        $key =~ s/^\s+|\s+$//g;
        $val =~ s/^\s+|\s+$//g;

        # Remove one pair of simple quotes if present.
        $val =~ s/^['"]//;
        $val =~ s/['"]$//;

        die "[ERROR] Empty config key found in $file\n"
            if $key eq "";

        $cfg{$key} = $val;
    }

    close $FH;

    return %cfg;
}

sub get_conf_required {
    my ($cfg_ref, $key) = @_;

    die "[ERROR] Required config parameter missing: $key\n"
        unless exists $cfg_ref->{$key}
            && defined $cfg_ref->{$key}
            && $cfg_ref->{$key} ne "";

    return $cfg_ref->{$key};
}

# ============================================================
# Validation helpers
# ============================================================

sub validate_bool_01 {
    my ($name, $value) = @_;

    die "[ERROR] $name must be 0 or 1. Observed: $value\n"
        unless defined $value && $value =~ /^[01]$/;

    return 1;
}

sub validate_positive_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a positive integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/ && $value >= 1;

    return 1;
}

sub validate_nonnegative_integer {
    my ($name, $value) = @_;

    die "[ERROR] $name must be a non-negative integer. Observed: $value\n"
        unless defined $value && $value =~ /^\d+$/;

    return 1;
}

sub check_executable {
    my ($cmd, $name) = @_;

    die "[ERROR] Empty executable path for $name\n"
        unless defined $cmd && $cmd ne "";

    if ($cmd =~ m{/}) {
        die "[ERROR] $name executable not found or not executable: $cmd\n"
            unless -x $cmd;
    } else {
        my $ret = system("command -v $cmd >/dev/null 2>&1");
        die "[ERROR] $name executable not found in PATH: $cmd\n"
            if $ret != 0;
    }

    return 1;
}

sub check_bam_index {
    my ($bam_file) = @_;

    my $bai1 = "$bam_file.bai";

    my $bai2 = $bam_file;
    $bai2 =~ s/\.bam$/.bai/i;

    die "[ERROR] BAM index not found for: $bam_file\n"
      . "        Expected one of:\n"
      . "        $bai1\n"
      . "        $bai2\n"
        unless -s $bai1 || -s $bai2;

    return 1;
}

# ============================================================
# SAM / SA helpers
# ============================================================

sub parse_sa_tag {
    my @fields = @_;

    for my $i (11 .. $#fields) {
        if (defined $fields[$i] && $fields[$i] =~ /^SA:Z:(.+)$/) {
            return (1, $1);
        }
    }

    return (0, "NA");
}

sub parse_sa_entries {
    my ($sa_tag) = @_;

    my @entries;

    return @entries
        unless defined $sa_tag
            && $sa_tag ne ""
            && $sa_tag ne "NA";

    # SA tag format:
    #   rname,pos,strand,CIGAR,mapQ,NM;
    for my $item (split /;/, $sa_tag) {
        next if !defined $item || $item =~ /^\s*$/;

        my @f = split /,/, $item;

        next unless @f >= 6;

        my ($chr, $pos, $strand, $cigar, $mapq, $nm) = @f[0 .. 5];

        for ($chr, $pos, $strand, $cigar, $mapq, $nm) {
            $_ = "" unless defined $_;
            s/^\s+|\s+$//g;
        }

        next unless $chr ne "";
        next unless $pos =~ /^\d+$/;
        next unless $strand =~ /^[+-]$/;
        next unless $cigar ne "" && $cigar ne "*";
        next unless $mapq =~ /^\d+$/;

        $nm = "NA" if !defined $nm || $nm eq "";

        push @entries, {
            chr    => $chr,
            pos    => $pos,
            strand => $strand,
            cigar  => $cigar,
            mapq   => $mapq,
            nm     => $nm,
        };
    }

    return @entries;
}

sub cigar_ref_length {
    my ($cigar) = @_;

    return 0
        unless defined $cigar
            && $cigar ne ""
            && $cigar ne "*";

    my $len = 0;

    while ($cigar =~ /(\d+)([MIDNSHP=X])/g) {
        my ($n, $op) = ($1, $2);

        # Operations consuming reference:
        # M, D, N, =, X
        if ($op =~ /^[MDN=X]$/) {
            $len += $n;
        }
    }

    return $len;
}

sub infer_sv_interval {
    my %args = @_;

    my $primary_chr   = $args{primary_chr};
    my $primary_start = $args{primary_start};
    my $primary_end   = $args{primary_end};
    my $sa_chr        = $args{sa_chr};
    my $sa_start      = $args{sa_start};
    my $sa_end        = $args{sa_end};

    my %ret = (
        left_breakpoint  => "NA",
        right_breakpoint => "NA",
        sv_chr           => "NA",
        sv_start         => "NA",
        sv_end           => "NA",
        sv_length        => "NA",
        junction_type    => "NA",
    );

    unless (
        defined $primary_chr
        && defined $sa_chr
        && $primary_chr eq $sa_chr
    ) {
        $ret{junction_type} = "Interchromosomal";
        return %ret;
    }

    my ($left_start, $left_end, $right_start, $right_end);

    if ($primary_start <= $sa_start) {
        ($left_start,  $left_end)  = ($primary_start, $primary_end);
        ($right_start, $right_end) = ($sa_start, $sa_end);
    } else {
        ($left_start,  $left_end)  = ($sa_start, $sa_end);
        ($right_start, $right_end) = ($primary_start, $primary_end);
    }

    $ret{left_breakpoint}  = $left_end;
    $ret{right_breakpoint} = $right_start;

    if ($left_end < $right_start - 1) {
        my $sv_start  = $left_end + 1;
        my $sv_end    = $right_start - 1;
        my $sv_length = $sv_end - $sv_start + 1;

        $ret{sv_chr}        = $primary_chr;
        $ret{sv_start}      = $sv_start;
        $ret{sv_end}        = $sv_end;
        $ret{sv_length}     = $sv_length;
        $ret{junction_type} = "Deletion_Gap";

        return %ret;
    }

    if ($left_end == $right_start - 1) {
        $ret{sv_chr}        = $primary_chr;
        $ret{sv_length}     = 0;
        $ret{junction_type} = "Adjacent_No_Gap";

        return %ret;
    }

    $ret{sv_chr}        = $primary_chr;
    $ret{junction_type} = "Overlap_or_Complex";

    return %ret;
}

# ============================================================
# SAM flag helpers
# ============================================================

sub is_paired {
    return ($_[0] & 0x1) ? 1 : 0;
}

sub is_unmapped {
    return ($_[0] & 0x4) ? 1 : 0;
}

sub is_reverse {
    return ($_[0] & 0x10) ? 1 : 0;
}

sub is_secondary {
    return ($_[0] & 0x100) ? 1 : 0;
}

sub is_duplicate {
    return ($_[0] & 0x400) ? 1 : 0;
}

sub is_supplementary {
    return ($_[0] & 0x800) ? 1 : 0;
}

# ============================================================
# General helpers
# ============================================================

sub shell_quote {
    my ($str) = @_;

    die "[ERROR] Undefined shell argument\n"
        unless defined $str;

    return "''" if $str eq "";

    return $str
        if $str =~ /^[A-Za-z0-9_\.\-\/\:=,\+]+$/;

    $str =~ s/'/'\\''/g;

    return "'$str'";
}

sub usage {
    return <<'USAGE';
Usage:
  perl bin/extract_sa_split_reads.pl \
    --conf /abs/path/conf/hcm_exondel.conf \
    --bam /abs/path/SAMPLE.target.bam \
    --sample SAMPLE_ID \
    --out /abs/path/results/SAMPLE/02.split_reads/SAMPLE.split_reads.tsv

Required arguments:
  --conf      HCMExonDel config file. --config is also accepted.
  --bam       Coordinate-sorted and indexed target BAM generated by extract_target_bam.pl.
  --sample    Sample ID.
  --out       Output SA split-read deletion event TSV file.

Required config parameters:
  SAMTOOLS
  MIN_MAPQ
  EXCLUDE_DUPLICATES
  SPLIT_READ_THREADS

Output:
  One row represents one deletion-like SA split-read event.

Output columns:
  Sample
  Read_Name
  Flag
  Primary_Chrom
  Primary_Start
  Primary_End
  Primary_CIGAR
  Primary_MAPQ
  Primary_Strand
  SA_Chrom
  SA_Start
  SA_End
  SA_CIGAR
  SA_MAPQ
  SA_Strand
  SA_NM
  Left_Breakpoint
  Right_Breakpoint
  SV_Chrom
  SV_Start
  SV_End
  SV_Length
  Junction_Type
  SA_Tag

Notes:
  1. Input BAM must be SAMPLE.target.bam, not the original WGS BAM.
  2. This script scans the whole target BAM directly.
  3. Only Junction_Type=Deletion_Gap events are written to output.
  4. Primary alignment MAPQ and SA alignment MAPQ are both filtered by MIN_MAPQ.
USAGE
}

